96	        LocalDate claimDate = date != null ? date : today;
97	        LocalDate dueBy = claimDate.plusDays(sheet.termsFor(person.gradeOn(claimDate), claimDate));
98	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), claimDate, dueBy,
99	                noteOf(note), corrects, claims.lastListed(sheetId) + 1));
100	        added.logStatus(user, today, shownDue(sheet, added, person));
101	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, added, added.getNumber()));
102	        rollup.recordChanges(sheetId, user, before);
103	        return added;
104	    }
105	
106	    /** Change a claim's amount, date, note and the claim it corrects; a missing date takes the sheet's today. Only
107	     *  a draft can be changed: to change an open claim, void it and add a new one. Refused when its date, as it is
108	     *  or as it would become, is inside a closed period, or when it would be a correction that does not name a
109	     *  SETTLED claim of its person. */
110	    @Transactional
111	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
112	            String corrects) {
113	        sheets.load(sheetId, user);
114	        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
115	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
116	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
117	        if (claim.getStatus() != ClaimStatus.DRAFT) {
118	            throw new ResponseStatusException(HttpStatus.CONFLICT,
119	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
120	        }
121	        refuseIfClosed(sheetId, claim.getDate());
122	        refuseIfClosed(sheetId, date != null ? date : today);
123	        refuseIfRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(), date != null ? date : today);
124	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
125	        Rollup.Figures before = rollup.of(sheetId);
126	        claim.setAmount(scaled(amount));
127	        claim.setCorrects(corrects);
128	        claim.setDate(date != null ? date : today);
129	        claim.setNote(noteOf(note));
130	        Claim edited = claims.saveAndFlush(claim);
131	        Person person = people.findByIdAndSheetId(edited.getPersonId(), sheetId).orElseThrow();
132	        audit.recordOnCommit(entry("CLAIM_EDITED", user, person, edited, edited.getNumber()));
133	        rollup.recordChanges(sheetId, user, before);
134	        return edited;
135	    }
136	
137	    /**
138	     * Move a claim to a new status; a move its current status does not allow is refused. Opening a
139	     * claim gives it its next number (the sheet's next, or the next in its period while the sheet numbers per
140	     * period) and records who opened it; voiding it keeps its number, which is
141	     * never given again; settling it fixes its due: the figure a statement binds it to, else its amount
142	     * at the rate in force on its date of its person's grade in force on that date, as rates are now, with the late charge it has gained
143	     * added on top, so later rate changes leave it as it is. The user
144	     * who opened a claim cannot settle it, and a clerk settling it when that due is above the sheet's clerk limit
145	     * makes it PENDING instead, for a steward to approve or reject (a claim with no due is within any limit); a
146	     * steward settles anything. A claim dated inside a closed period cannot move. The sheet is locked
147	     * first, so moves on one sheet are made one at a time and no number is given twice.
148	     */
149	    @Transactional
150	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
151	        sheets.load(sheetId, user);
152	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
153	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
154	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
155	        refuseIfClosed(sheetId, claim.getDate());
156	        if (!claim.getStatus().canBecome(next)) {
157	            throw new ResponseStatusException(HttpStatus.CONFLICT,
158	                    "A " + claim.getStatus() + " claim cannot become " + next);
159	        }
160	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
161	            throw new ResponseStatusException(HttpStatus.CONFLICT,
162	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
163	        }
164	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
165	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
166	        }
167	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
168	        BigDecimal due = dueNow(sheet, claim, person);
169	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheet, user, due)) {
170	            next = ClaimStatus.PENDING;
171	        }
172	        Rollup.Figures before = rollup.of(sheetId);
173	        String number = claim.getNumber();
174	        claim.setStatus(next);
175	        if (next == ClaimStatus.OPEN) {
176	            number = nextNumber(sheet, claim.getDate());
177	            claim.setNumber(number);
178	            claim.setOpenedBy(user);
179	        } else if (next == ClaimStatus.SETTLED) {
180	            claim.setSettledDue(due);
181	        }
182	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
183	        Claim changed = claims.saveAndFlush(claim);
184	        String event = switch (next) {
185	            case OPEN -> "CLAIM_OPENED";
186	            case PENDING -> "CLAIM_PENDING";
187	            case SETTLED -> "CLAIM_SETTLED";
188	            case VOID -> "CLAIM_VOIDED";
189	            case DRAFT -> throw new IllegalStateException();
190	        };
191	        String line = entry(event, user, person, changed, number);
192	        if (next == ClaimStatus.SETTLED) {
193	            line += " due=" + dueText(changed);
194	        }
195	        audit.recordOnCommit(line);
196	        rollup.recordChanges(sheetId, user, before);
197	        return changed;
198	    }
199	
200	    /** Defer an OPEN claim until a day after the sheet's today: until the sheet's today reaches that day it counts
201	     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that
202	     *  is not OPEN, a day not after today and a claim dated inside a closed period. */
203	    @Transactional
204	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
205	        sheets.load(sheetId, user);
206	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
207	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
208	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
209	        refuseIfClosed(sheetId, claim.getDate());
210	        if (claim.getStatus() != ClaimStatus.OPEN) {
211	            throw new ResponseStatusException(HttpStatus.CONFLICT,
212	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
213	        }
214	        if (!until.isAfter(sheet.getToday())) {
215	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a day after today");
216	        }
217	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
218	        Rollup.Figures before = rollup.of(sheetId);
219	        claim.setDeferredUntil(until);
220	        Claim deferred = claims.saveAndFlush(claim);
221	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, deferred, deferred.getNumber()) + " until=" + until);
222	        rollup.recordChanges(sheetId, user, before);
223	        return deferred;
224	    }
225	
226	    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its live
227	     *  figure with the late charge it has gained). Refused for a clerk, for the user who opened the claim, for a
228	     *  claim that is not PENDING and for one dated inside a closed period. */
229	    @Transactional
230	    public Claim approve(String sheetId, String user, long id) {
231	        sheets.load(sheetId, user);
232	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
233	        Claim claim = pendingClaim(sheetId, user, id);
234	        if (user.equals(claim.getOpenedBy())) {
235	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
236	        }
237	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
238	        BigDecimal due = dueNow(sheet, claim, person);
239	        Rollup.Figures before = rollup.of(sheetId);
240	        claim.setStatus(ClaimStatus.SETTLED);
241	        claim.setSettledDue(due);
242	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
243	        Claim changed = claims.saveAndFlush(claim);
244	        audit.recordOnCommit(entry("CLAIM_APPROVED", user, person, changed, changed.getNumber())
245	                + " due=" + dueText(changed));
246	        rollup.recordChanges(sheetId, user, before);
247	        return changed;
248	    }
249	
250	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
251	     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
252	     *  dated inside a closed period. */
253	    @Transactional
254	    public Claim reject(String sheetId, String user, long id, String reason) {
255	        sheets.load(sheetId, user);
256	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
257	        Claim claim = pendingClaim(sheetId, user, id);
258	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
259	        Rollup.Figures before = rollup.of(sheetId);
260	        claim.setStatus(ClaimStatus.OPEN);
261	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
262	        Claim changed = claims.saveAndFlush(claim);
263	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
264	                + " reason=" + reason.trim());
265	        rollup.recordChanges(sheetId, user, before);
266	        return changed;
267	    }
268	
269	    /** A steward re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an open
270	     *  claim bound by no statement (its live figure at today's rates, grades and floor, with the late charge it
271	     *  would have gained by today on top), and its status log gains a SETTLED line. Refused for a clerk, for a
272	     *  claim that is not SETTLED and for one dated inside a closed period. */
273	    @Transactional
274	    public Claim resettle(String sheetId, String user, long id) {
275	        sheets.load(sheetId, user);
276	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
277	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
278	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
279	        refuseIfClosed(sheetId, claim.getDate());
280	        if (claim.getStatus() != ClaimStatus.SETTLED) {
281	            throw new ResponseStatusException(HttpStatus.CONFLICT,
282	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
283	        }
284	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
285	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
286	        }
287	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
288	        BigDecimal live = liveNow(sheet, claim, person);
289	        BigDecimal due = live == null ? null : live.add(lateChargeAsOpen(claim, live, sheet));
290	        Rollup.Figures before = rollup.of(sheetId);
291	        String old = dueText(claim);
292	        claim.setSettledDue(due);
293	        claim.logStatus(user, sheet.getToday(), due);
294	        Claim changed = claims.saveAndFlush(claim);
295	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, changed, changed.getNumber())
296	                + " old=" + old + " new=" + dueText(changed));
297	        rollup.recordChanges(sheetId, user, before);
298	        return changed;
299	    }
300	
301	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
302	     *  loses any figure a statement bound it to (it is live again until its new person's next statement), and is
303	     *  listed as its new person's newest claim. Refused for a clerk, for a SETTLED or VOID claim, for a move to the
304	     *  person it is already of, for one dated inside a closed period or after the new person retired, and for a
305	     *  correction the new person has no SETTLED claim of that number for. */
306	    @Transactional
307	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
308	        sheets.load(sheetId, user);
309	        sheetStore.findLockedById(sheetId).orElseThrow();
310	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
311	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
312	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
313	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
314	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
315	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
316	        }
317	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
318	            throw new ResponseStatusException(HttpStatus.CONFLICT,
319	                    "A " + claim.getStatus() + " claim cannot be reassigned");
320	        }
321	        if (claim.getPersonId().equals(to.getId())) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
323	        }
324	        refuseIfClosed(sheetId, claim.getDate());
325	        refuseIfRetired(to, claim.getDate());
326	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
327	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
328	        Rollup.Figures before = rollup.of(sheetId);
329	        claim.unbind();
330	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
331	        Claim moved = claims.saveAndFlush(claim);
332	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
333	                + " from=" + from.getName() + " to=" + to.getName());
334	        rollup.recordChanges(sheetId, user, before);
335	        return moved;
336	    }
337	
338	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
339	     *  dated inside a closed period. */
340	    private Claim pendingClaim(String sheetId, String user, long id) {
341	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
342	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
343	        refuseIfClosed(sheetId, claim.getDate());
344	        if (claim.getStatus() != ClaimStatus.PENDING) {
345	            throw new ResponseStatusException(HttpStatus.CONFLICT,
346	                    "A " + claim.getStatus() + " claim is not waiting for approval");
347	        }
348	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
349	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
350	        }
351	        return claim;
352	    }
353	
354	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
355	     *  gained on top; null when it has no figure. */
356	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
357	        BigDecimal live = liveNow(sheet, claim, person);
358	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained.
359	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
360	        return figure == null ? null : figure.add(lateCharge(claim, figure, sheet));
361	    }
362	
363	    /** A claim's live figure as rates, grades and the floor are now, bound by no statement; null when its grade has
364	     *  no rate in force on its date. */
365	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
366	        String sheetId = sheet.getId();
367	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
368	                .map(Rate::getRate)
369	                .map(rate -> liveFigure(claim, rate, sheet.floorOn(claim.getDate()), sheet.roundingFor(roundingDate(claim,
370	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
371	                .orElse(null);
372	    }
373	
374	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
375	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
376	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
377	    }
378	
379	    private static String dueText(Claim claim) {
380	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
381	    }
382	
383	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
384	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
385	    private String nextNumber(Sheet sheet, LocalDate date) {
386	        if (!sheet.numbersPerPeriod()) {
387	            return String.valueOf(sheet.nextClaimNumber());
388	        }
389	        String prefix = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
390	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
391	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
392	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
393	        String number = sequence.next();
394	        sequences.save(sequence);
395	        return number;
396	    }
397	
398	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
399	     *  clerk limit (a claim with no due is within any limit). */
400	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
401	        BigDecimal limit = sheet.getClerkLimit();
402	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
403	            return false;
404	        }
405	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
406	    }
407	
408	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
409	     *  and a claim that is not a correction but names one. */
410	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
411	        if (amount.signum() >= 0) {
412	            if (corrects != null) {
413	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
414	                        "Only a correction (a negative amount) names a claim it corrects");
415	            }
416	            return;
417	        }
418	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
419	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
420	        if (!settled) {
421	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
422	                    "A correction must name the number of a SETTLED claim of the same person");
423	        }
424	    }
425	
426	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
427	    private void refuseIfClosed(String sheetId, LocalDate date) {
428	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
429	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
430	        }
431	    }
432	
433	    /** Refuse a claim dated after its person's retirement date. */
434	    private static void refuseIfRetired(Person person, LocalDate date) {
435	        if (person.refusesClaimOn(date)) {
436	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
437	                    "That claim is dated after " + person.getName() + " retired");
438	        }
439	    }
440	
441	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
442	    private static String entry(String event, String user, Person person, Claim claim, String number) {
443	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
444	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
445	                + (number == null ? "" : " number=" + number);
446	    }
447	
448	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
449	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
450	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
451	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
452	    }
453	
454	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
455	     *  claim of the same person it corrects. */
456	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
457	        if (claim.getCorrects() == null) {
458	            return claim.getDate();
459	        }
460	        return sheetClaims.stream()
461	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
462	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
463	    }
464	
465	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: the late percent in force on its date of
466	     *  the figure for every full 30 days past the day it is due by, rounded as the claim rounds; 0.00 when not overdue,
467	     *  it has no figure, or it is a correction. */
468	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
469	        BigDecimal none = BigDecimal.ZERO.setScale(2);
470	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
471	            return none;
472	        }
473	        return lateChargeAsOpen(claim, figure, sheet);
474	    }
475	
476	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
477	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
478	        BigDecimal none = BigDecimal.ZERO.setScale(2);
479	        if (figure == null || claim.isCorrection()) {
480	            return none;
481	        }
482	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
483	        return periods <= 0 ? none : dueOn(figure, sheet.latePctOn(claim.getDate()).multiply(BigDecimal.valueOf(periods)),
484	                sheet.roundingFor(claim.getDate()));
485	    }
486	
487	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds, raised to the floor
488	     *  (the one in force on its date) unless it is a correction. */
489	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, BigDecimal floor, RoundingMode rounding) {
490	        BigDecimal due = dueOn(claim.getAmount(), rate, rounding);
491	        return claim.isCorrection() ? due : floored(due, floor);
492	    }
493	
494	    /** A live due raised to the sheet's floor when it is below it. */
495	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
496	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
497	    }
498	
499	    private static BigDecimal scaled(BigDecimal amount) {
500	        return amount.setScale(2, RoundingMode.UNNECESSARY);
501	    }
502	
503	    private static String noteOf(String note) {
504	        return note == null ? "" : note.trim();
505	    }
506	}
